import numpy as np
def equation(t, x, v, params):
    c = np.cos(params[7]*t+params[8])
    s = np.exp(-params[9]*t)
    base = params[0] + params[1]*x + params[2]*x**3 + params[3]*v + params[4]*v*np.abs(v) + params[5]/v + params[6]*np.log(x)
    return base + s*c*(params[10] + params[11]*x + params[12]*v)
